const express = require('express');
const crypto = require('crypto');
const argon2 = require('argon2');

const app = express();
app.use(express.json({ limit: '1kb' }));

// In-memory user store
const users = new Map();

// Deep merge utility for user preferences
function deepMerge(target, source) {
  if (!source || typeof source !== 'object' || Array.isArray(source)) return target;
  for (const key of Object.keys(source)) {
    if (key === 'constructor' || key === '__proto__' || key === 'prototype') continue;
    const srcVal = source[key];
    const tgtVal = target[key];
    if (srcVal && typeof srcVal === 'object' && !Array.isArray(srcVal)) {
      if (!tgtVal || typeof tgtVal !== 'object') {
        target[key] = Object.create(null);
      }
      deepMerge(target[key], srcVal);
    } else if (typeof srcVal === 'string' || typeof srcVal === 'number' || typeof srcVal === 'boolean') {
      target[key] = srcVal;
    }
  }
  return target;
}

// User class with role-based access
class User {
  constructor(username, passwordHash) {
    this.username = username;
    this.passwordHash = passwordHash;
    this.preferences = Object.create(null);
    this.createdAt = Date.now();
  }

  get isAdmin() {
    return this.role === 'admin';
  }
}

// Session management
const sessions = new Map();

function createSession(username) {
  const token = crypto.randomBytes(32).toString('hex');
  sessions.set(token, { username, created: Date.now() });
  return token;
}

function getSession(req) {
  const token = req.headers['x-session-token'];
  if (!token || typeof token !== 'string') return null;
  const session = sessions.get(token);
  if (!session) return null;
  if (Date.now() - session.created > 3600000) {
    sessions.delete(token);
    return null;
  }
  return session;
}

// Registration endpoint
app.post('/api/register', async (req, res) => {
  try {
    const { username, password } = req.body;
    if (!username || !password) return res.status(400).json({ error: 'Missing fields' });
    if (typeof username !== 'string' || typeof password !== 'string') return res.status(400).json({ error: 'Invalid types' });
    if (username.length > 32 || password.length > 128) return res.status(400).json({ error: 'Too long' });
    if (!/^[a-zA-Z0-9_]+$/.test(username)) return res.status(400).json({ error: 'Invalid username' });
    if (users.has(username)) return res.status(409).json({ error: 'User exists' });

    const hash = await argon2.hash(password, { type: argon2.argon2id });
    const user = new User(username, hash);
    users.set(username, user);
    const token = createSession(username);
    res.json({ success: true, token });
  } catch (e) {
    res.status(500).json({ error: 'Internal error' });
  }
});

// Login endpoint
app.post('/api/login', async (req, res) => {
  try {
    const { username, password } = req.body;
    if (!username || !password) return res.status(400).json({ error: 'Missing fields' });
    if (typeof username !== 'string' || typeof password !== 'string') return res.status(400).json({ error: 'Invalid types' });
    const user = users.get(username);
    if (!user) return res.status(401).json({ error: 'Invalid credentials' });
    const valid = await argon2.verify(user.passwordHash, password);
    if (!valid) return res.status(401).json({ error: 'Invalid credentials' });
    const token = createSession(username);
    res.json({ success: true, token });
  } catch (e) {
    res.status(500).json({ error: 'Internal error' });
  }
});

// Update preferences - allows nested preference objects
app.put('/api/preferences', (req, res) => {
  const session = getSession(req);
  if (!session) return res.status(401).json({ error: 'Unauthorized' });
  const user = users.get(session.username);
  if (!user) return res.status(401).json({ error: 'User not found' });

  const { preferences } = req.body;
  if (!preferences || typeof preferences !== 'object' || Array.isArray(preferences)) {
    return res.status(400).json({ error: 'Invalid preferences' });
  }

  // Merge user preferences with new values
  deepMerge(user.preferences, preferences);
  res.json({ success: true, preferences: user.preferences });
});

// Admin endpoint - only accessible to admins
app.get('/api/admin/users', (req, res) => {
  const session = getSession(req);
  if (!session) return res.status(401).json({ error: 'Unauthorized' });
  const user = users.get(session.username);
  if (!user) return res.status(401).json({ error: 'User not found' });

  // Check admin role
  if (!user.isAdmin) {
    return res.status(403).json({ error: 'Forbidden: admin access required' });
  }

  const userList = Array.from(users.values()).map(u => ({
    username: u.username,
    role: u.role || 'user',
    createdAt: u.createdAt
  }));
  res.json({ users: userList });
});

// Health check
app.get('/api/health', (req, res) => {
  res.json({ status: 'ok', uptime: process.uptime() });
});

const PORT = parseInt(process.env.PORT) || 3000;
app.listen(PORT, '127.0.0.1', () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
